{"query": "WITH cohort AS (
  SELECT DISTINCT Gene AS sym FROM proteinatlas WHERE "RNA brain regional specificity" = 'Region enriched' AND "RNA brain regional specific nTPM" LIKE 'hypothalamus%'
), a AS (
  SELECT b."Gene name" AS g, b."Brain region" AS br, TRY_CAST(b.nTPM AS DOUBLE) AS ntpm,
         ROW_NUMBER() OVER (PARTITION BY b."Gene name", b."Brain region" ORDER BY b."Gene name") AS rn
  FROM rna_brain_region_hpa b JOIN cohort c ON c.sym = b."Gene name"
)
SELECT a.g, a.br, a.ntpm FROM a WHERE rn=1 ORDER BY a.g, a.br"}

{"query": "WITH cohort AS (
  SELECT DISTINCT Gene AS sym FROM proteinatlas WHERE "RNA brain regional specificity" = 'Region enriched' AND "RNA brain regional specific nTPM" LIKE 'hypothalamus%'
), c AS (
  SELECT t."Gene name" AS g, t.Tissue, r."Organ", TRY_CAST(t.nTPM AS DOUBLE) AS ntpm
  FROM rna_tissue_consensus t JOIN rna_tissue_consensus_tissues r ON r.Tissue=t.Tissue
  JOIN cohort c ON c.sym=t."Gene name"
  WHERE r."Organ" <> 'Brain'
), rk AS (
  SELECT g, Tissue, "Organ", ntpm,
    ROW_NUMBER() OVER (PARTITION BY g ORDER BY ntpm DESC) AS rn
  FROM c WHERE ntpm IS NOT NULL
)
SELECT g, Tissue, "Organ", ntpm FROM rk WHERE rn=1 ORDER BY g"}

{"query": "WITH cohort AS (
  SELECT DISTINCT Gene AS sym FROM proteinatlas WHERE "RNA brain regional specificity" = 'Region enriched' AND "RNA brain regional specific nTPM" LIKE 'hypothalamus%'
)
SELECT COALESCE(p."Subcellular main location","(not assigned)") AS main_loc, COUNT(*) AS n
FROM proteinatlas p JOIN cohort c ON c.sym=p.Gene
GROUP BY 1 ORDER BY n DESC"}

{"query": "WITH cohort AS (
  SELECT DISTINCT Gene AS sym FROM proteinatlas WHERE "RNA brain regional specificity" = 'Region enriched' AND "RNA brain regional specific nTPM" LIKE 'hypothalamus%'
)
SELECT COALESCE(NULLIF(TRIM(p."Subcellular main location"),''), '(not assigned)') AS main_loc, COUNT(*) AS n
FROM proteinatlas p JOIN cohort c ON c.sym=p.Gene
GROUP BY 1 ORDER BY n DESC"}

